 private Drawable glass(int radius){return new Glass(dp(radius),prefs.getBoolean("shine",true));}
 private static class Glass extends Drawable {
  final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);final RectF bounds=new RectF(),inner=new RectF();final Path clip=new Path();final int radius;final boolean shine;Shader base,edge;
  Glass(int radius,boolean shine){this.radius=radius;this.shine=shine;}
  @Override protected void onBoundsChange(Rect b){bounds.set(b);inner.set(bounds);inner.inset(1,1);base=new LinearGradient(b.left,b.top,b.right,b.bottom,new int[]{0xff36384f,0xff20243b,0xff141a2f},null,Shader.TileMode.CLAMP);edge=new LinearGradient(0,b.top,0,b.bottom,new int[]{0x95ffffff,0x0affffff,0x18ffffff},new float[]{0,.35f,1},Shader.TileMode.CLAMP);clip.reset();clip.addRoundRect(bounds,radius,radius,Path.Direction.CW);}
  @Override public void draw(Canvas c){paint.setStyle(Paint.Style.FILL);paint.setShader(base);c.drawRoundRect(bounds,radius,radius,paint);if(shine){paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1.5f);paint.setShader(edge);c.drawRoundRect(inner,radius,radius,paint);paint.setStyle(Paint.Style.FILL);paint.setShader(null);paint.setColor(0x12ffffff);c.save();c.clipPath(clip);c.drawOval(bounds.left-bounds.width()*.15f,bounds.top-bounds.height()*.8f,bounds.right+bounds.width()*.25f,bounds.top+bounds.height()*.21f,paint);c.restore();}paint.setShader(null);}
  @Override public void getOutline(Outline o){o.setRoundRect(getBounds(),radius);}
  @Override public void setAlpha(int a){} @Override public void setColorFilter(ColorFilter cf){} @Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}
 }
