 private void requestRefresh(){WindowManager.LayoutParams p=getWindow().getAttributes();p.preferredDisplayModeId=0;p.preferredRefreshRate=0;PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);if(active&&prefs.getBoolean("highRefresh",true)&&!pm.isPowerSaveMode()){Display d=getWindowManager().getDefaultDisplay();Display.Mode cur=d.getMode(),best=null;for(Display.Mode m:d.getSupportedModes())if(m.getPhysicalWidth()==cur.getPhysicalWidth()&&m.getPhysicalHeight()==cur.getPhysicalHeight()&&m.getRefreshRate()<=121&&(best==null||m.getRefreshRate()>best.getRefreshRate()))best=m;if(best!=null&&best.getRefreshRate()>=85){p.preferredDisplayModeId=best.getModeId();p.preferredRefreshRate=best.getRefreshRate();}}getWindow().setAttributes(p);}
