 private LinearLayout panel(String title){close(false);dialog=new Dialog(this);LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setPadding(dp(18),dp(12),dp(18),dp(18));outer.setBackground(glass(27));LinearLayout head=new LinearLayout(this);TextView name=label(title,21);name.setTypeface(null,Typeface.BOLD);head.addView(name,new LinearLayout.LayoutParams(0,dp(50),1));head.addView(topButton("×",()->close(true)),new LinearLayout.LayoutParams(dp(45),dp(50)));outer.addView(head);ScrollView scroll=new ScrollView(this);scroll.setOverScrollMode(View.OVER_SCROLL_NEVER);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);scroll.addView(box);outer.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(outer);dialogContent=outer;dialog.show();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams lp=new WindowManager.LayoutParams();lp.copyFrom(w.getAttributes());lp.width=WindowManager.LayoutParams.MATCH_PARENT;lp.height=(int)(getResources().getDisplayMetrics().heightPixels*.82f);lp.gravity=Gravity.BOTTOM;lp.dimAmount=.3f;w.setAttributes(lp);}if(!minimal()){outer.setAlpha(.75f);outer.setTranslationY(dp(25));outer.animate().alpha(1).translationY(0).setDuration(duration()).setInterpolator(new DecelerateInterpolator()).start();}return box;}
