 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==61){if(result==RESULT_OK)configureWidget();else cancelWidget();}else if(request==62){if(result==RESULT_OK)finishWidget();else cancelWidget();}else if((request==71||request==72)&&result==RESULT_OK&&data!=null&&data.getData()!=null)saveImage(data.getData(),request==72);}
